bar         = "qs"

notif_manager = "dunst"
polkit_agent = "/usr/lib/polkit-kde-authentication-agent-1"

applet_removable_media = "udiskie --no-automount --smart-tray"
applet_network = "nm-applet --indicator"
applet_bluetooth =   "blueman-applet"


